def _parse_igmp_frame(raw):
    """解析通过帧检查、VLAN 准入、入端口 forwarding 的 IPv4 帧。

    返回 (None, None) 表示非 IPv4；(address, message) 表示 IPv4：
    address 为 4 字节目的地址，message 为 None（非协议 2 或外层非法）
    或 (kind, group)，kind ∈ report/leave/query/invalid。
    """
    if raw[12:14] == FRAME_DECODE_TAG:
        ethertype_offset = 16
    else:
        ethertype_offset = 14
    if ethertype_offset + 2 > len(raw) - 4:
        return None, None
    ethertype = (raw[12] << 8) | raw[13] if ethertype_offset == 14 else (
        (raw[16] << 8) | raw[17]
    )
    if ethertype != IGMP_ETHERTYPE_IPV4:
        return None, None
    ip_start = ethertype_offset + 2
    ip_payload = raw[ip_start:-4]
    if len(ip_payload) < 20:
        return 0, None  # 外层非法
    version_ihl = ip_payload[0]
    if (version_ihl >> 4) != 4:
        return 0, None
    ihl = version_ihl & 0x0F
    if ihl < 5:
        return 0, None
    ip_header = ip_payload[:ihl * 4]
    if len(ip_header) > len(ip_payload):
        return 0, None
    total_length = (ip_header[2] << 8) | ip_header[3]
    if total_length < ihl * 4 or total_length > len(ip_payload):
        return 0, None
    if _ipv4_checksum(ip_header) != 0:
        return 0, None
    flags_fragment = (ip_header[6] << 8) | ip_header[7]
    mf = flags_fragment & 0x2000
    fragment_offset = flags_fragment & 0x1FFF
    dst_addr = bytes(ip_header[16:20])
    if mf or fragment_offset:
        # 分片帧：不是可识别 IGMP 报文，但 IPv4 外层合法
        return dst_addr, None
    if ip_header[9] != IGMP_PROTOCOL:
        return dst_addr, None
    segment = ip_payload[ihl * 4:total_length]
    if len(segment) < IGMP_MIN_IP_PAYLOAD:
        return dst_addr, ("invalid", None)
    message = segment[:IGMP_MIN_IP_PAYLOAD]
    if _ipv4_checksum(message) != 0:
        return dst_addr, ("invalid", None)
    mtype = message[0]
    group = bytes(message[4:8])
    if mtype == IGMP_TYPE_QUERY:
        # Query 组地址须为 0.0.0.0（通用查询）；本实现不识别组特定查询
        if group != b"\x00\x00\x00\x00":
            return dst_addr, ("invalid", None)
        return dst_addr, ("query", group)
    if mtype in (IGMP_TYPE_V2_REPORT, IGMP_TYPE_V1_REPORT):
        # Report 组地址须为非 224.0.0.x 的合法 IPv4 组播地址
        group_int = int.from_bytes(group, "big")
        if group_int >> 24 != 0xE0 or (group_int & 0xFFFFFF) < 0x010000:
            return dst_addr, ("invalid", None)
        return dst_addr, ("report", group)
    if mtype == IGMP_TYPE_LEAVE:
        group_int = int.from_bytes(group, "big")
        if group_int >> 24 != 0xE0 or (group_int & 0xFFFFFF) < 0x010000:
            return dst_addr, ("invalid", None)
        return dst_addr, ("leave", group)
    return dst_addr, ("invalid", None)


def igmp_snoop_work(
    bridges, links, ports, events, stp_limit, igmp_limit,
):
    """igmp-snoop-decode 工作量：forward-stp 既有口径 + 每帧 N+P+1。

    N 为事件中帧的累计数（逐事件递增），P 为端口数；链路项不加 IGMP
    部分。等于上限合法，首次超过抛 IgmpWorkLimit；stp 部分先按既有
    forward-stp 公式判定（沿用 ForwardStpWorkLimit 与 forward_stp_work
    的逐事件口径）。
    """
    forward_stp_work(bridges, links, ports, events, stp_limit)
    P = len(ports)
    N = 0
    work = 0
    for item in events:
        if item[0] == "frame":
            work += N + P + 1
            N += 1
            if work > igmp_limit:
                raise IgmpWorkLimit


